  if (!Number.isInteger(poured) || poured < 0 || poured > 1000000000) return 'poured is a whole number from 0 to 10^9.';
  if (!Number.isInteger(query_row) || query_row < 0 || query_row > 99) return 'query_row is a whole number from 0 to 99.';
  if (!Number.isInteger(query_glass) || query_glass < 0 || query_glass > query_row) return 'query_glass is a whole number from 0 to query_row.';
