function champagneTower(poured, query_row, query_glass) {
  // Build the whole 100-row tower, each glass pulling what spills from the two glasses above it.
  const received = [[poured]];
  for (let i = 1; i < 100; i++) {
    received.push([]);
    for (let j = 0; j <= i; j++) {
      const fromLeft = j > 0 ? Math.max(0, received[i - 1][j - 1] - 1) / 2 : 0;
      const fromRight = j < i ? Math.max(0, received[i - 1][j] - 1) / 2 : 0;
      received[i].push(fromLeft + fromRight);
    }
  }
  const amount = received[query_row][query_glass];
  return amount > 1 ? 1 : amount;
}

