function generate(rand, size) {
  const poured = size === 'large'
    ? (rand() < 0.3 ? 1000000000 - Math.floor(rand() * 1000) : Math.floor(Math.pow(10, 3 + rand() * 6)))
    : (rand() < 0.2 ? Math.floor(rand() * 4) : Math.floor(Math.pow(10, rand() * 3)));
  const lowest = size === 'large' ? 60 : 0, highest = size === 'large' ? 99 : 14;
  // Most glasses end up empty or full, so usually aim at a partly filled one in the allowed rows.
  const partial = [];
  let row = [poured];
  for (let r = 0; r <= highest; r++) {
    if (r >= lowest) row.forEach((amount, c) => { if (amount > 0 && amount < 1) partial.push([r, c]); });
    const next = new Array(r + 2).fill(0);
    row.forEach((amount, c) => { if (amount > 1) { next[c] += (amount - 1) / 2; next[c + 1] += (amount - 1) / 2; } });
    row = next;
  }
  if (partial.length && rand() < 0.6) return [poured, ...partial[Math.floor(rand() * partial.length)]];
  const query_row = lowest + Math.floor(rand() * (highest - lowest + 1));
  return [poured, query_row, Math.floor(rand() * (query_row + 1))];
}
